"""Third edition: motivate the model, then earn each mathematical object."""
from story import D,P,M,I,O,slider,btn

def revise(slides):
    by={s['id']:s for s in slides}
    def edit(id,body=None,**kw):
        if body is not None:kw['body']=body
        by[id].update(kw)
        if 'title' in kw:by[id]['question']=kw['title']
    def add(id,title,kind,builds=1,controls='',notes='',answer='',provenance='ANALYTICAL / EXACT · original teaching construction',source=None):
        s=dict(by['three-objects']);s.update(id=id,title=title,question=title,body=D(kind,controls),builds=builds,notes=notes,answer=answer,idea='',provenance=provenance,source=source,appendix=False)
        by[id]=s
    edit('start',D('ped-cover'),title='Generative Modelling I',idea='',provenance='OBSERVED MNIST test digit · original conceptual diagram',notes='We have learned to recognize and compare inputs. Today: learn the structure and variation needed to create another plausible example. Start with the task; postpone the architecture.',answer='Learn a distribution over possible data, then sample from it.')
    edit('recall',D('ped-recognize'),builds=2,title='Recognizing a digit is one task. Drawing one is another.',idea='',notes='First reveal the label for a supplied image. Then ask for a new image without supplying an input image. The decoder-only language model was already generative; we return to that familiar example shortly.',provenance='OBSERVED MNIST · conceptual tasks; classifier label shown for illustration')
    add('many-answers','What if several answers are reasonable?','ped-completion',2,notes='Ask for possible completions of the authored partial sketch. Several answers can be plausible. This motivates distributions over outputs. It is an application preview, not a claim that our unconditional MNIST model performs inpainting.',answer='Represent possible answers and their uncertainty instead of insisting on a single average.',provenance='ILLUSTRATIVE · original vector sketches; conditional-completion preview')
    add('generation-baselines','What have these two generators missed?','ped-baselines',3,notes='Replay uses the first eight training examples. Independent pixels use frequencies estimated from all 60,000 binary training images and seed 667. Ask students to predict the second panel before revealing it. Both are samplers; replay alone does not demonstrate generalization, and independent pixels discard stroke dependencies.',answer='We need to learn structure and variation beyond replay or independent pixel frequencies.',provenance='MEASURED · training-image replay and fitted independent Bernoulli baseline; seed 667')
    edit('sevens',title='Which properties of these sevens vary together?',notes='Look at slant, thickness and proportions in actual examples. Hidden causes are a modelling hypothesis. We do not claim the learned latent axes correspond to these named properties.')
    edit('another-digit',D('ped-success'),builds=2,title='What would count as a good generator?',idea='',notes='These are the same first eight fixed-seed VAE-16 decoder means. Inspect imperfections. Ask separately about plausible individual samples, coverage, and generalization. A small panel cannot prove coverage or absence of memorization. No labels were used in training.',answer='Plausible samples, adequate coverage, and generalization beyond replay.',provenance='MEASURED · original VAE-16, fixed prior seed; unselected decoder means')
    add('generation-inference','The same model, viewed in two directions','ped-directions',3,notes='Start from the generative process: prior z, decoder distribution, observed x. Reverse the question after observing x: which latent values explain it? The inference arrow denotes a conditional question, not an inverse decoder.',answer='Generation samples x given z. Inference asks for a distribution over z given x.',provenance='CONCEPTUAL · original generation and inference diagram',source='https://jaan.io/what-is-variational-autoencoder-vae-tutorial')
    add('evidence-sum','How probable is this observation?','ped-evidence',3,notes='Use the exact three-state latent example. Prior probabilities .2,.5,.3 and observation likelihoods .1,.8,.2 yield contributions .02,.40,.06, so p(x)=.48. Normalize those contributions to obtain the posterior. In a continuous neural latent model the sum becomes an integral, generally without an exact tractable solution.',answer='Average the conditional likelihood over the prior: p(x)=.48 in this toy.',source='https://arxiv.org/abs/1312.6114')
    add('approximate-inference','Let one encoder learn to propose explanations','ped-amortized',3,notes='The true posterior is defined by the generative model but is generally hard to compute. q is a tractable approximation. A shared neural encoder predicts its parameters for each image; we amortize inference across images. Learned network weights are distinct from the per-image latent variables.',answer='qφ(z|x) approximates pθ(z|x); the same learned encoder serves many images.',provenance='OBSERVED MNIST inputs / ILLUSTRATIVE posterior curves · original diagram',source='https://jaan.io/what-is-variational-autoencoder-vae-tutorial')
    add('kl-meaning','How expensive is the wrong probability model?','ped-kl',3,slider('qmass','q(A)',.05,.95,.8,.05)+slider('pmass','p(A)',.05,.95,.5,.05),notes='Samples come from q. At each outcome compute log q minus log p, then average under q. Individual contributions may be negative; their sum is nonnegative. With q=(.8,.2), p=(.5,.5), KL=.192745 nats. Natural logs give nats. The logarithmic scoring/coding interpretation is idealized expected extra log loss.',answer='KL(q||p) is expected extra negative log probability when data drawn from q are scored using p.',source='https://lilianweng.github.io/posts/2018-08-12-vae/#vae-variational-autoencoder')
    add('kl-direction','Why does the direction of KL matter?','ped-kl-direction',2,notes='Keep q=(.8,.2), p=(.5,.5). Swapping direction changes both the log ratio and the averaging distribution. KL(q||p)=.192745; KL(p||q)=.223144. If p assigns zero mass to an event with positive q mass, KL(q||p) diverges. KL is not a symmetric distance. In VAE inference we use the q-to-posterior direction.',answer='The first distribution chooses which outcomes receive weight in the average.',source='https://lilianweng.github.io/posts/2018-08-12-vae/#vae-variational-autoencoder')
    add('kl-modes','Cover both groups, or concentrate on one?','ped-kl-modes',2,btn('kl-wide','Cover both groups')+btn('kl-narrow','Choose the left group'),notes='Original two-mode figure inspired by the KL comparison discussed in Lilian Weng and Eric Jang. Target p is an equal mixture of N(-2,.55²) and N(2,.55²). Compare q=N(0,2.1²) with q=N(-2,.65²). Display both KL directions using quadrature on [-12,12] with spacing .005. These are two candidates, not claimed globally optimal fits. Reverse KL can prefer a concentrated approximation in this restricted family; it does not universally choose one mode.',answer='Forward KL penalizes poor coverage of target mass; reverse KL also penalizes placing approximate-posterior mass in target gaps.',provenance='NUMERICAL QUADRATURE · illustrative densities; original diagram; no trained model',source='https://lilianweng.github.io/posts/2018-08-12-vae/#vae-variational-autoencoder')
    add('elbo-gap','How can we improve a bound on the evidence?','ped-bound',3,slider('fit','approximation step',0,2,0,1),notes='Exact discrete toy from the preceding evidence slide. Hold the generative model fixed, so log p(x)=log .48 is fixed. Improve q through three explicitly chosen distributions. The computed gap is KL(q||true posterior). The final q equals the true posterior and closes the gap. A neural model generally cannot compute this gap exactly; we can in this finite toy.',answer='log p(x)=ELBO+KL(q||posterior). Nonnegative KL makes ELBO a lower bound.',source='https://arxiv.org/abs/1312.6114')
    add('two-kls','Two KL terms. Two different comparisons.','ped-two-kls',2,notes='The gap compares q with the true posterior. Expanding the bound yields expected log likelihood minus KL to the prior. The latter is computable for our Gaussian family. For fixed θ, improving q tightens the bound; when θ changes the evidence changes too.',answer='Posterior KL explains the bound; prior KL appears in its computable expansion.',source='https://lilianweng.github.io/posts/2018-08-12-vae/#loss-function-elbo')
    edit('elbo',notes='Now name the complete negative ELBO. The reconstruction term is an expectation under q; the KL to the unit Gaussian prior is analytical. β=1 gives the standard objective. The preceding exact toy explains why these terms occur.',answer='Minimizing the negative ELBO optimizes a lower bound on marginal log likelihood.')
    add('autograd-sampling','Which draw keeps the gradient path?','ped-autograd',3,notes='The measured PyTorch check confirms that Normal(mu,sigma).sample() does not retain this pathwise autograd connection; explicit mu+sigma*eps does, and rsample supplies the reparameterized interface. Hold eps fixed during a backward pass; draw fresh noise for a new Monte Carlo sample. Other gradient estimators exist.',answer='Use an explicit differentiable transformation of independent noise, or rsample().',provenance='VERIFIED PYTORCH · experiments/pedagogy_evidence.py; scalar chain rule is exact',source='https://pytorch.org/docs/stable/distributions.html#pathwise-derivative')
    add('beta-experiment','What changes when we strengthen the prior penalty?','ped-beta',3,btn('beta-0','β = 0')+btn('beta-1','β = 1')+btn('beta-4','β = 4'),notes='Three new 2D VAEs, same initialization/data order/noise seeds, first 12,000 training images, 12 epochs. BCE sums pixels; KL sums latent dimensions; both average examples. Same held-out images and prior draws. These are separate trained checkpoints, not a continuous model slider. β=0 retains stochastic sampling. No claim of disentanglement or universal optimal β.',answer='Inspect reconstruction, prior samples and measured KL together. Stronger pressure can reduce information carried by z.',provenance='MEASURED · controlled β=0,1,4 sweep; d=2; 12k train / 10k test; 12 epochs; seed 667')
    edit('latent-plane',notes='Spend four minutes here. Predict the decode before moving. Inspect a nearby point and its 3 by 3 neighborhood. Compare the selected location with its prior density, then draw from the prior. The evenly spaced grid is a map, not a gallery of equally probable samples. Saved-weight inference and nearest-grid fallback are separately labelled. Learned axes need not have named meanings.',answer='The grid maps z to decoder probabilities; the prior tells us how frequently we visit regions of that grid.')
    # Every original concept remains available. Distribution basics are a quick recall route.
    blocks=[
      ('Why generate?',7,['start','chapter-0','recall','many-answers','generation-baselines','sevens','another-digit','distribution-question']),
      ('Learning a distribution',5,['chapter-1','discrete','gaussian','area','multimodal','recipe','learn-density','two-abilities']),
      ('We already know one',2,['chapter-2','language','pixels','whole-object']),
      ('From randomness to data',7,['chapter-3','prior','latent-generator','which-z','autoencoder','ae-experiment','ae-sampling']),
      ('Inference, KL and the bound',15,['chapter-4','generation-inference','evidence-sum','approximate-inference','encoder-distribution','three-objects','kl-meaning','kl-direction','kl-modes','elbo-gap','two-kls','elbo']),
      ('Training through randomness',13,['chapter-5','opaque-sample','independent-noise','same-distribution','computation-graph','sample-arithmetic','gradient-arithmetic','code','code-implementation','autograd-sampling']),
      ('What does the trained model learn?',17,['chapter-6','two-requirements','likelihood','bernoulli-example','kl-interactive','kl-arithmetic','full-vae','train-generate','measured-models','measured-generation','latent-plane','paths-and-curves','training-curves','beta-experiment']),
      ('Learning through a discriminator',10,['chapter-7','another-signal','discriminator','train-discriminator','train-generator','alternate','gan-numbers','gan-training','coverage']),
      ('Invertible generation',4,['chapter-8','invertible','change-of-variables','four-answers','forward-noise','next'])]
    questions=['What would a useful generator have to learn?','Where should probability mass go?','Our language model already generates. How?','Why can reconstruction succeed while sampling fails?','Which latent values explain this image?','How does a gradient pass through a random draw?','How do reconstruction and generation change together?','Which network learns on this step?','Could many small transformations make generation easier?']
    result=[]
    explicit={'start':20,'chapter-0':10,'recall':45,'many-answers':60,'generation-baselines':105,'sevens':60,'another-digit':70,'distribution-question':50,'chapter-6':10,'two-requirements':40,'likelihood':20,'bernoulli-example':105,'kl-interactive':30,'kl-arithmetic':105,'full-vae':85,'train-generate':70,'measured-models':25,'measured-generation':35,'latent-plane':240,'paths-and-curves':50,'training-curves':25,'beta-experiment':180}
    for k,(name,minutes,ids) in enumerate(blocks):
        chapter=by[f'chapter-{k}'];chapter.update(title=name,question=questions[k],body=f'<div class="chapter-number">{k:02}</div>'+P(questions[k],'chapter-question')+P('From randomness to data','chapter-thread'),notes=f'Chapter plan: {minutes} minutes. Ask: {questions[k]}')
        weights=[1 if by[id].get('chapter') else max(2,by[id]['builds']) for id in ids]
        total=sum(weights);seconds=[round(minutes*60*w/total) for w in weights];seconds[-1]+=minutes*60-sum(seconds)
        for id,sec in zip(ids,seconds):
            s=by[id];s.update(section=f'{k:02} · {name}',planned_seconds=explicit.get(id,sec));result.append(s)
        assert sum(s['planned_seconds'] for s in result if s['section']==f'{k:02} · {name}')==minutes*60
    original={s['id'] for s in slides if not s['appendix']};assert original.issubset({s['id'] for s in result})
    result.extend(s for s in slides if s['appendix'])
    assert sum(s['planned_seconds'] for s in result if not s['appendix'])==4800
    return result
